export async function listTools() {
  return [
    {
      name: 'note_create',
      description: 'Create a new note with a title and body.',
      inputSchema: {
        type: 'object',
        properties: {
          title: { type: 'string', description: 'The note title.' },
          body: { type: 'string', description: 'The note body.' }
        },
        required: ['title', 'body']
      }
    },
    {
      name: 'note_get',
      description: 'Get a stored note by its id.',
      inputSchema: {
        type: 'object',
        properties: {
          note_id: { type: 'string', description: 'The id of the note to retrieve.' }
        },
        required: ['note_id']
      }
    }
  ];
}

export async function callTool(name, args) {
  if (name === 'note_create') {
    const title = args.title;
    const body = args.body;
    if (typeof title !== 'string' || title.trim() === '') {
      throw new Error('title is required and must be a non-empty string');
    }
    if (typeof body !== 'string' || body.trim() === '') {
      throw new Error('body is required and must be a non-empty string');
    }
    const id = nextId();
    notes.set(id, { id, title, body });
    return {
      content: [{ type: 'text', text: `Created note ${id}: ${title}` }]
    };
  }
  if (name === 'note_get') {
    const noteId = args.note_id;
    if (typeof noteId !== 'string' || noteId.trim() === '') {
      throw new Error('note_id is required and must be a non-empty string');
    }
    const note = notes.get(noteId);
    if (!note) {
      throw new Error(`note not found: ${noteId}`);
    }
    return {
      content: [{ type: 'text', text: `${note.title}\n\n${note.body}` }]
    };
  }
  throw new Error(`unknown tool: ${name}`);
}
